select  from ai_agent_session
where is_deleted = 0
  and create_user_id = #{createUserId}
  and pin_order = 0

    and aid = #{aid}


    and is_debug = #{debug}

order by modify_time desc, id desc
limit #{limit}

select  from ai_agent_session
where is_deleted = 0
  and create_user_id = #{createUserId}
  and pin_order > 0

    and aid = #{aid}

order by pin_order desc, modify_time desc

mapper.update:
update ai_agent_session
set status = #{status}, modify_time = #{modifyTime}
where id = #{id} and is_deleted = 0

update ai_agent_session
set status = #{status}, modify_time = #{modifyTime}
where session_id = #{sessionId} and is_deleted = 0

update ai_agent_session
set title = #{title}, modify_time = #{modifyTime}
where id = #{id} and is_deleted = 0

update ai_agent_session
set pin_order = #{pinOrder}, modify_time = #{modifyTime}
where id = #{id} and is_deleted = 0

update ai_agent_session
set modify_time = #{modifyTime}
where session_id = #{sessionId} and is_deleted = 0

update ai_agent_session
set is_deleted = 1, modify_time = #{modifyTime}
where id = #{id} and is_deleted = 0
